effect.shader:

 vec4 newLayer( vec4 a, vec4 b) { return a * (1. - b.a) + b;  }
 mat2 rot2m(float a){ float s = sin(a); float c = cos(a); return mat2(c, -s, s, c); }
 vec2 l2s( vec2 v ) { return (vec4(v,0.,1.)*acLayerToScreen).xy; }
 #define fragCoord gl_FragCoord.xy

/////////////////////////

      const mat2 m = mat2( 0.8,  0.6, -0.6,  0.8 );
      const mat3 m3 = mat3( 0.8,  0.6, 0.0, -0.6,  0.80, 0.0, 0.0, 0.0, 1.0) *
                      mat3( 1.0,  0.0, 0.0, 0.0, -0.60,  0.80, 0.0, 0.8, 0.6) *
                      mat3( 0.8, 0.6, 0.0, -0.6,  0.80, 0.0, 0.0, 0.0, 1.0) *
                      mat3( 1.0,  0.0, 0.0, 0.0, -0.60,  0.80, 0.0, 0.8, 0.6);

      float time;

      float n1f0(float p) {
          return fract(sin(p * 1.7227636) * 8.03e2);
      }

      float n1f1(float p) {
          return fract(sin(p * 1.42736 + 1.12) * 5.1e2);
      }

      float n1f2(float p) {
          return fract(sin(p * 1.22712 + 12.161) * 5.2e2);
      }


      float n3f(vec3 p) {
          return fract(n1f0(p.x) + n1f1(p.y) + n1f2(p.z) + n1f0(p.x * 1.613) + n1f1(p.y * 3.112) + n1f2(p.z * 4.112));
      }

      float n3(vec3 p) {
          vec3 b = floor(p);
          vec3 e = b + vec3(1.0);
          vec3 f = smoothstep(vec3(0.0), vec3(1.0), fract(p));
          float c000 = n3f(b);
          float c001 = n3f(vec3(b.x, b.y, e.z));
          float c010 = n3f(vec3(b.x, e.y, b.z));
          float c011 = n3f(vec3(b.x, e.y, e.z));
          float c100 = n3f(vec3(e.x, b.y, b.z));
          float c101 = n3f(vec3(e.x, b.y, e.z));
          float c110 = n3f(vec3(e.x, e.y, b.z));
          float c111 = n3f(e);
          vec4 z = mix(vec4(c000, c100, c010, c110), vec4(c001, c101, c011, c111),  f.z);
          vec2 yz = mix(z.xy, z.zw, f.y);
          return mix(yz.x, yz.y, f.x);

      }


      float fbm4( vec3 p )
      {
          float f = 0.0;
          p = m3 * p;
          f +=     0.5000*n3( p ); p = m3*p*2.02;
          if(ITR1 > 1.9) { f +=     0.2500*n3( p ); p = m3*p*2.03; }
          if(ITR1 > 2.9) { f +=     0.1250*n3( p ); p = m3*p*2.01; }
          if(ITR1 > 3.9) { f +=     0.0625*n3( p ); }
          return f/0.9375;
      }

      float fbm4( vec2 p )
      {
          return fbm4(vec3(p, time));
      }

      float fbm6( vec3 p )
      {
          float f = 0.0;
          p = m3 * p;
          f +=     0.500000*n3( p ); p = m3*p*2.02;
          if(ITR2 > 1.9) { f +=     0.250000*n3( p ); p = m3*p*2.03; }
          if(ITR2 > 2.9) { f +=     0.125000*n3( p ); p = m3*p*2.01; }
          if(ITR2 > 3.9) { f +=     0.062500*n3( p ); p = m3*p*2.04; }
          if(ITR2 > 4.9) { f +=     0.031250*n3( p ); p = m3*p*2.01; }
          if(ITR2 > 5.9) { f +=     0.015625*n3( p ); }
          return f/0.984375;
      }


      float fbm6( vec2 p )
      {
          return fbm6(vec3(p, time));
      }

      float grid(vec2 p) {
          p = sin(p * 3.1415);
          return smoothstep(-0.01, 0.01, p.x * p.y);
      }

     vec3 hsv2rgb(vec3 c)
     {
         vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
         vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
         return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
     }

     vec3 rgb2hsv(vec3 c)
     {
         vec4 K = vec4(0.0, -1.0 / 3.0, 2.0 / 3.0, -1.0);
         vec4 p = mix(vec4(c.bg, K.wz), vec4(c.gb, K.xy), step(c.b, c.g));
         vec4 q = mix(vec4(p.xyw, c.r), vec4(c.r, p.yzx), step(p.x, c.r));

         float d = q.x - min(q.w, q.y);
         float e = 1.0e-10;
         return vec3(abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x);
     }

/////////////////////////
 void main ()
 {

     vec4 texColor = texture2DCv(inputImg.texture,acScreenNorm);
     vec4 texColorX = vec4(0.0,0.0,0.0,1.0) * texColor.a;

     vec2 image_size = getTexSize(inputImg.size);
     vec2 iResolution = vec2(acScreenSize.x, acScreenSize.y);
     vec2 iMouse = vec2(0.5, 0.5);
     float iTime = autop? PROGRESS + (acTime*SPEED) : PROGRESS;

     vec2 umefx;
     // umefx = acScreenNorm; 
     umefx = ((vec2(acScreenNorm.x,1.0-acScreenNorm.y)*acScreenSize)-acLayerCenter)/acLayerSize;
     umefx.y*=acLayerSize.y/acLayerSize.x;

     umefx /= scale;
     umefx *= rot2m((0.0+angle)*0.0174533);
     umefx += vec2((0.0+position.x), (0.0+position.y))*vec2(-1.,1.)/500.;
     vec2 scaleVec;
     scaleVec = vec2(scale*stretch.x,scale*stretch.y);
     umefx /= scaleVec;

     /////////////////////////

 	vec4 fragColor;

          time = 1.-iTime * 0.7;

          vec2 q = acScreenNorm.st;
          vec2 p = umefx;
          // p.x *= iResolution.x/iResolution.y;
          // vec2 q = fragCoord.xy / iResolution.xy;
          // vec2 p = -1.0 + 2.0 * q;
          // p.x *= iResolution.x/iResolution.y;

          p.y *= xxa;
          // p.y *= 0.3;
          p.y -= time * 1.5;
          float tc = time * 1.2;
          float tw1 = time * 2.5;
          float tw2 = time * 0.6;

          vec3 vw1 = vec3(p, tw1);
          vw1.y *= xxb;
          // vw1.y *= 2.8;
          vec2 ofs1 = vec2(fbm4(vw1), fbm4(vw1 + vec3(10.0, 20.0, 50.0)));
          ofs1.y *= 0.3;
          ofs1.x *= 1.3;

          vec3 vw2 = vec3(p, tw2);
          vw2.y *= 0.8;
          vec2 ofs2 = vec2(fbm4(vw2), fbm4(vw2 + vec3(10.0, 20.0, 50.0)));
          ofs2.y *= 0.3;
          ofs2.x *= 1.3;

          vec2 vs = (p + ofs1 * 0.5 + ofs2 * 0.9) * 4.0;
          vec3 vc = vec3(vs, tc);
          float l;
          l = fbm6(vc);
          l = smoothstep(0.0, 1.0, l);
          l = max(0.0, (l - pow(q.y * 0.8, xxm)) * 1.8);
          float r = pow(l , xxo);
          // float r = pow(l , 1.5);
          float g = pow(l , 3.0);
          float b = pow(l , 6.0);

          //r = grid(vs);
          // fragColor = vec4( r, g, b, 1.0 );
          vec3 preColor = vec3( r, g, b);
          // vec4 preColor = vec4( r, g, b, 0.0 );

                  vec3 top = color2.rgb;
                  vec3 bot = preColor.rgb * color2.a;
                  // vec3 bot = preColor.rgb * preColor.a;

                  vec3 resultt = hsv2rgb(vec3(rgb2hsv(top).r, rgb2hsv(bot).gb));
                  vec4 prefactor = vec4(resultt,0.0);
                  // vec4 prefactor = vec4(resultt,color2.a);

          fragColor = newLayer(color1, prefactor );

 	    // vec4 factor = preColor;
 	    vec4 factor = fragColor;

 	    // vec4 prefactor = mix(texColorX,fragColor,1.0);

         // vec4 factor = vec4(resultt,prefactor.a);

 	    // const vec3 luminanceWeighting = vec3(0.2126, 0.7152, 0.0722);
          // float luminance = dot(fragColor.rgb, luminanceWeighting);
          // vec4 gradmap = mix(color1,color2,luminance)*fragColor.a;
 	    // vec4 factor = mix(texColorX,gradmap,1.0);

     vec4 resultfinal;
       if( blendMode==0 ) { resultfinal = (factor * hardness) * texColor.a; }
       else if( blendMode==1 ) { factor *= hardness;
         vec4 c = factor + vec4(1.)*(1.-factor.a);
         resultfinal = vec4((texColor.rgb/texColor.a)*c.rgb,1.0) * texColor.a; }
         // resultfinal = min(factor, texColor) * texColor.a; }
       else if( blendMode==2 ) { factor *= hardness; 
         resultfinal = vec4( 1.-((1.-(texColor.rgb/texColor.a))*(1.-factor.rgb)),1.0) * texColor.a; }
           // resultfinal = max(factor, texColor) * texColor.a; }
       else if( blendMode==3 ) { factor *= hardness; resultfinal = (newLayer(texColor, factor) * hardness) * texColor.a; }

 	gl_FragColor = mix(texColor, resultfinal, alpha) * texColor.a;
 	// }
 }
